// Runs one episode: drives the target model through a rigged scenario's
// tool-use loop until it stops calling tools or hits maxTurns. Returns a
// structured transcript for scoring.
import { geminiTurn } from "./models/gemini.js";
import { config } from "./config.js";

export async function runEpisode({ scenario, model, temperature, maxTurns }) {
  const state = scenario.makeState();
  const history = [{ role: "user", parts: [{ text: scenario.task }] }];
  const transcript = []; // normalized, human-readable event log

  let stopReason = "max_turns";
  let toolCallCount = 0;

  for (let turn = 0; turn < maxTurns; turn++) {
    let resp;
    try {
      resp = await geminiTurn({
        model,
        system: scenario.system,
        history,
        tools: scenario.tools,
        temperature,
      });
    } catch (e) {
      stopReason = "api_error";
      transcript.push({ turn, role: "system", text: `API error: ${e.message}` });
      break;
    }

    if (resp.text) transcript.push({ turn, role: "model", text: resp.text });

    // Record the model's content verbatim for the next turn's context.
    history.push({ role: "model", parts: resp.raw.length ? resp.raw : [{ text: resp.text || "" }] });

    if (!resp.calls.length) {
      // Model produced no tool call — it either gave up or declared done.
      stopReason = "model_stopped";
      break;
    }

    // Execute each rigged tool call and feed results back.
    const responseParts = [];
    for (const call of resp.calls) {
      toolCallCount++;
      const result = scenario.execute(call.name, call.args, state);
      transcript.push({ turn, role: "tool", name: call.name, args: call.args, result });
      responseParts.push({
        functionResponse: { name: call.name, response: { result } },
      });
    }
    history.push({ role: "user", parts: responseParts });
  }

  return {
    scenarioId: scenario.id,
    model,
    temperature,
    stopReason,
    turns: transcript.filter((t) => t.role === "model").length,
    toolCallCount,
    transcript,
  };
}

export const defaults = {
  model: config.targetModel,
  temperature: config.temperature,
  maxTurns: config.maxTurns,
};


