// Central config + tiny .env loader (no dependencies).
import { readFileSync } from "node:fs";

function loadDotEnv() {
  try {
    const raw = readFileSync(new URL("../.env", import.meta.url), "utf8");
    for (const line of raw.split("\n")) {
      const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
      if (!m) continue;
      const [, k, v] = m;
      if (process.env[k] === undefined || process.env[k] === "") {
        process.env[k] = v.replace(/^["']|["']$/g, "");
      }
    }
  } catch {
    /* no .env file — rely on real env vars */
  }
}
loadDotEnv();

export const config = {
  // Target model under test.
  targetModel: process.env.TARGET_MODEL || "gemini-2.5-pro",

  // Judge model (Anthropic) for severity scoring.
  judgeModel: process.env.JUDGE_MODEL || "claude-opus-4-8",

  geminiApiKey: process.env.GEMINI_API_KEY || "",
  anthropicApiKey: process.env.ANTHROPIC_API_KEY || "",

  // Episodes per scenario.
  n: Number(process.env.N || 8),
  // Max agent turns before we declare the episode over.
  maxTurns: Number(process.env.MAX_TURNS || 16),
  // Concurrent episodes in flight.
  concurrency: Number(process.env.CONCURRENCY || 4),

  // Sampling temperature for the target (higher => more behavioral variance).
  temperature: Number(process.env.TEMPERATURE || 1.0),

  // How many top examples to surface in the summary.
  topK: Number(process.env.TOP_K || 10),
};


