// Orchestrator: run N episodes per scenario at concurrency, score each,
// rank by severity, and write transcripts + a ranked summary to runs/.
import { mkdirSync, writeFileSync } from "node:fs";
import { config } from "./config.js";
import { scenarios } from "./scenarios/index.js";
import { runEpisode } from "./agent.js";
import { scoreEpisode } from "./scorer.js";

function stamp() {
  // Date.* is fine here (top-level script, not a workflow context).
  return new Date().toISOString().replace(/[:.]/g, "-");
}

// Simple promise pool to cap concurrent in-flight tasks.
async function pool(items, limit, worker) {
  const results = new Array(items.length);
  let i = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) {
      const idx = i++;
      results[idx] = await worker(items[idx], idx);
    }
  });
  await Promise.all(runners);
  return results;
}

