    console.warn("Warning: no ANTHROPIC_API_KEY — LLM-judge disabled, falling back to structural signals.\n");
  }

  // Optional scenario filter: `node src/run.js phantom-fix broken-shell`
  const filter = process.argv.slice(2);
  const active = filter.length ? scenarios.filter((s) => filter.includes(s.id)) : scenarios;

  // Build the full work list: N episodes per active scenario.
  const jobs = [];
  for (const scenario of active) {
    for (let k = 0; k < config.n; k++) jobs.push({ scenario, k });
